//! Cargo-driven `svchost.exe` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is svchost-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_wmainCRTStartup"),
        "x86_64" => ("x86_64-pc-windows-gnu", "wmainCRTStartup"),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "wmainCRTStartup"),
        o => panic!("svchost-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["body", "engine:uuid", "import:netapi32", "import:ole32", "import:advapi32", "import:rpcrt4", "import:kernel32", "import:ntdll", "engine:delayimp_rust"],
        "x86_64" => &["body", "engine:uuid", "import:netapi32", "import:ole32", "import:advapi32", "import:rpcrt4", "import:kernel32", "import:ntdll", "engine:delayimp_rust"],
        "aarch64" => &["body", "engine:uuid", "import:netapi32", "import:ole32", "import:advapi32", "import:rpcrt4", "import:kernel32", "import:ntdll", "engine:delayimp_rust"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/base/services/svchost",
        "base/services/svchost",
        "@std",
        "sdk/lib/pseh/include",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &["UNICODE", "WINVER=0x502", "_UNICODE", "_WIN32_WINNT=0x502"];

    Linker::new(target_json)
        .rust_staticlib("svchost-rust")
        .c_from_compile_db("svchost_shims", &["base/services/svchost/security.cxx"])
        .whole_c_objects("svchost_shims")
        .rc("base/services/svchost/svchost.rc", rc_includes, rc_flags, rc_defines)
        .delay_import_lib("dll/win32/netapi32/netapi32.spec", "netapi32.dll", "netapi32")
        .delay_import_lib("dll/win32/ole32/ole32.spec", "ole32.dll", "ole32")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/rpcrt4/rpcrt4.spec", "rpcrt4.dll", "rpcrt4")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .link(ModuleKind::Win32Exe {
            entry: entry.into(),
            subsystem: "console:5.01".into(),
        });
}
